import pandas as pd

def find_students_who_improved(scores: pd.DataFrame) -> pd.DataFrame:
    if scores.empty:
        return pd.DataFrame(columns=['student_id', 'subject', 'first_score', 'latest_score'])

    res = []
    grouped = scores.groupby(['student_id', 'subject'])
    for (sid, subj), group in grouped:
        if len(group['exam_date'].unique()) >= 2:
            sorted_g = group.sort_values(by='exam_date')
            first_sc = sorted_g.iloc[0]['score']
            latest_sc = sorted_g.iloc[-1]['score']
            if latest_sc > first_sc:
                res.append({
                    'student_id': sid,
                    'subject': subj,
                    'first_score': first_sc,
                    'latest_score': latest_sc
                })

    if not res:
        return pd.DataFrame(columns=['student_id', 'subject', 'first_score', 'latest_score'])

    df = pd.DataFrame(res)
    return df.sort_values(by=['student_id', 'subject'], ascending=[True, True])
